import{_ as l,h as i,i as e,c as d,v as o,p as n,x as r,m as s,e as p,S as c}from"./chunks/framework.Dvtg8yj2.js";const f=JSON.parse('{"title":"适配器热更新","description":"","frontmatter":{"title":"适配器热更新","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/adapter-hot-swap.md","filePath":"llm/adapter-hot-swap.md","lastUpdated":1788454257000}'),h={name:"llm/adapter-hot-swap.md"};function E(A,a,B,m,_,v){const t=i("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="适配器热更新" tabindex="-1">适配器热更新 <a class="header-anchor" href="#适配器热更新" aria-label="Permalink to &quot;适配器热更新&quot;">​</a></h1><div class="epigraph"><p>换一份 $A,B$ 不该等于重启引擎；进行中的 decode 必须钉住旧页，新请求才看见新版本，KV 与路由键一起换代。</p><footer>—— 对照多 LoRA 服务中适配器作为可换页对象，以及发布时的版本钉扎</footer></div><p><a href="/llm/lora">LoRA</a> 体积小，看起来可以像配置一样随时替换。生产里替换的是正在被若干请求逐步读的权重：某一步的 \\(A\\) 来自 v1、\\(B\\) 来自 v2，前向在数学上仍能跑完，语义已经不是任何一次训练的结果。热更新要保证的不是「文件能覆盖」，而是一次<strong>原子换代</strong>：旧版本对在途请求只读，新版本只对换代之后到达的请求可见，与该版本绑定的 KV 不得被新版本复用。本篇写这条约定，加载器实现见 <a href="/llm/lorax-serving">LoRAX</a>，合并态下的额外约束见 <a href="/llm/dlora">dLoRA</a>。不编造一篇名为 adapter hot-swap 的经典论文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>适配器的发布频率高于基座：策略改一句、分类头重训一晚、客户数据再灌一轮，都可能出一份新的 \\(A,B\\)。若更新路径是停引擎、拷文件、再启动，<a href="/llm/continuous-batching">连续批</a> 里所有流式连接断开，CUDA Graph 重捕获，冷启动的 TTFT 尖刺会写进当天的 P99。若更新路径是直接 <code>memcpy</code> 到正在服务的缓冲，decode 中途换权重，用户会看到风格突变、工具格式破裂，更糟的是安全策略 LoRA 在半句之后失效。</p><p>还有缓存。引擎内部的 <a href="/llm/prefix-caching">前缀缓存</a> 与集群 <a href="/llm/kv-aware-routing">KV 感知路由</a> 都把「模型身份」写进键。键若不含适配器版本，新权重会吃到旧 KV：位置编码还对，内容已经是另一套 \\(\\Delta W\\) 编出来的。表现为「提示没变、回答像在读旧说明书」。</p><h3 id="进行中的请求是钉住的快照" tabindex="-1">进行中的请求是钉住的快照 <a class="header-anchor" href="#进行中的请求是钉住的快照" aria-label="Permalink to &quot;进行中的请求是钉住的快照&quot;">​</a></h3><p>自回归把一次请求拆成许多迭代，每一迭代都读当前 \\(W_0\\) 与当前 \\(BA\\)。热更新若在迭代之间插入，等于在序列中途换模型。产品几乎总是不允许：聊天中途改人设、分类器中途改类别表，审计无法复盘。正确语义是请求级快照——<code>accept(request)</code> 时锁定 <code>(adapter_id, version)</code>，直到 EOS 或取消。新版本只影响锁定期之后的到达。</p><p><span class="marginnote">「热」指进程不重启、基座不重载，不指零等待。加载新页、校验形状、切路由、等旧引用计数归零，都可以是数百毫秒到数秒。看板应把这次发布标成一次计划内的尾延迟事件，而不是当成无成本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把适配器对象做成不可变页：一份 \\(A,B\\) 带内容哈希，引用计数等于「正在用它做前向的请求数」。发布 v2 时：</p><ol><li>加载 v2 到空闲缓冲，校验层名、秩、dtype、\\(\\alpha\\) 与基座是否可服务。失败则发布中止，v1 继续。</li><li>原子地把路由表里 <code>adapter_id → 当前版本</code> 从 v1 改为 v2。此后新请求只看见 v2。</li><li>v1 页保持只读，直到引用计数为零，再归还 HBM / CPU 缓存。</li><li>使与 v1 绑定的前缀 KV 失效，或把版本写入缓存键，让旧 KV 自然 miss。不要在 v2 请求上复用 v1 的块。</li></ol><p>合并态更严。若卡上跑的是 \\(W_0+B_1A_1\\)，热更新要么先解合并再换页，要么准备一份新的 \\(W&#39;=W_0+B_2A_2\\) 双缓冲切换。切的瞬间，运行集里不能混用两份满秩权重，除非引擎真的为两份 \\(W\\) 做了双背景——那已经是两份基座的显存账。<a href="/llm/punica">Punica</a> 的不合并路径更适合频繁换代：只换小页，背景 GEMM 不动。</p><h3 id="双缓冲与排水" tabindex="-1">双缓冲与排水 <a class="header-anchor" href="#双缓冲与排水" aria-label="Permalink to &quot;双缓冲与排水&quot;">​</a></h3><p>高峰期引用计数可能长时间不为零（一条 <code>max_tokens</code> 很大的写作）。发布不能无限等。策略有三：等到超时再<strong>取消</strong>仍钉 v1 的请求并 409/503；允许 v1/v2 在不合并核里共存直到自然结束（显存付两份适配器）；对超长请求在迭代边界<strong>抢占</strong>，让客户端重试——重试必须带幂等键，以免工具侧效果执行两次。双缓冲的容量要预留，否则「热更新」会在 KV 池已满时 OOM。</p><p>HTTP 契约：客户端应能指定版本或接受「服务端当前」。返回体带实际生效的版本哈希，便于客诉对照。<code>model</code> 字段若是别名，别名切换等于热更新，日志里要留下别名→哈希的解析。加载中的新请求进该适配器的隔离队列，不要用基座顶上并 200。</p>',16)),(e(),n(c,null,{default:r(()=>[p(t,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUB%5B%22%E5%8F%91%E5%B8%83%20v2%22%5D%20--%3E%20LOAD%5B%22%E5%8A%A0%E8%BD%BD%E5%B9%B6%E6%A0%A1%E9%AA%8C%E5%88%B0%E7%A9%BA%E9%97%B2%E9%A1%B5%22%5D%0A%20%20LOAD%20--%3E%20SWAP%5B%22%E5%8E%9F%E5%AD%90%E5%88%87%E8%B7%AF%E7%94%B1%EF%BC%9Aid%20%E2%86%92%20v2%22%5D%0A%20%20SWAP%20--%3E%20NEW%5B%22%E6%96%B0%E8%AF%B7%E6%B1%82%E9%92%89%20v2%22%5D%0A%20%20SWAP%20--%3E%20OLD%5B%22%E5%9C%A8%E9%80%94%E8%AF%B7%E6%B1%82%E9%92%89%20v1%20%E7%9B%B4%E5%88%B0%20EOS%22%5D%0A%20%20OLD%20--%3E%20DRAIN%5B%22%E5%BC%95%E7%94%A8%E8%AE%A1%E6%95%B0%E5%BD%92%E9%9B%B6%22%5D%0A%20%20DRAIN%20--%3E%20FREE%5B%22%E5%9B%9E%E6%94%B6%20v1%20%E9%A1%B5%E5%B9%B6%E5%A4%B1%E6%95%88%E5%85%B6%20KV%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>原子性来自「指针切换，而不是原地改矩阵」。SGMV 一类 gather 核吃的是页地址数组；把某 <code>adapter_id</code> 对应的指针从页 1 换成页 2，已启动的 kernel 仍用启动时拍下的地址，下一迭代才读新指针——因此切换应落在迭代边界，并与调度器的运行集更新同一把锁。若在 kernel 运行中改指针，就是数据竞争，不是热更新。</p><h3 id="版本必须写进-kv-与路由指纹" tabindex="-1">版本必须写进 KV 与路由指纹 <a class="header-anchor" href="#版本必须写进-kv-与路由指纹" aria-label="Permalink to &quot;版本必须写进 KV 与路由指纹&quot;">​</a></h3><p>KV 失效的原因是函数变了。同一 token 前缀，v1 与 v2 的键值投影不同，注意力分数不同。前缀缓存若只哈希 token 而不哈希适配器版本，就会把 v1 的 KV 喂给 v2。路由表同样：集群若按 <code>adapter_id</code> 粘滞却不按版本，会把请求打到仍持有旧 KV 的副本，表现为假命中、错回答。版本必须进入指纹。</p><p><span class="marginnote">安全类适配器（拒答风格、分类头）的热更新要当政策发版：先在影子流量比对类别分布，再切主路径。只换文件不比对，等于在生产做一次未评测的对齐。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不是所有「适配器」都能热更新。插层集合变了、新增模块、词表加了特殊 token，计算图已变，应走滚动重启，不要假装换页。基座权重本身的更新不是本篇范围：那是另一份数 GB 的对象，通常蓝绿副本。QLoRA 基座 4-bit 与 LoRA 的数值耦合若在 v2 改变缩放，仅换 \\(A,B\\) 可能溢出；校验规则要把量化配置算进去。</p><p>多卡 TP 下，每一张卡上的切片必须同版本；不能出现 rank 0 已切 v2、rank 1 仍 v1。切应做成栅栏：全部加载成功再一起改指针。跨区域见 <a href="/llm/multi-region-failover">多区域故障转移</a>：一区先切、一区后切的窗口里，同一用户来回打会看到两种人格——要么会话粘滞到区，要么接受短暂不一致并在网关写明。</p><p><span class="marginnote">不要用「覆盖同一路径上的 <code>.safetensors</code>」当发布。文件系统可见性、mmap 缓存、已经 map 进进程的旧页，三者不同步。发布物应是新对象键，旧键只读到引用为零。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>热更新是迭代边界上的指针切换：在途请求钉旧页，新请求钉新页；禁止一步之内 \\(A\\) 与 \\(B\\) 跨版本。</li><li>适配器版本必须进入 KV 缓存键与集群路由指纹，否则会复用错误的前缀状态。</li><li>合并态要双缓冲满秩权重或先解合并；不合并路径更适合频繁换代。</li><li>引用计数排水、超时取消、双页共存是容量问题，要预留 HBM。</li><li>图结构变化或词表变化应滚动重启；安全适配器按政策发版评测。</li><li>出处：对照 Punica / S-LoRA / LoRAX 把适配器当可换页对象的实现惯例，以及请求级快照的服务语义；无单独经典论文名。</li></ul>',11))])}const P=l(h,[["render",E]]);export{f as __pageData,P as default};
